def smallestLex(s):
    n = len(s)
    def dfs(start, end, prev_char):
        # If we have reached the end of the string, return True if the substring is valid
        if start == end:
            return all(ord(s[i]) == ord(prev_char) + 1 for i in range(start, n))

        # Try all possible substrings
        for i in range(start, end + 1):
            if all(ord(s[j]) == ord(prev_char) + 1 for j in range(start, i)):
                # Check if the rest of the string is valid
                if dfs(i + 1, end, s[i]):
                    return True

        return False

    # Check all possible operations
    for i in range(len(s)):
        # Try all possible substrings ending at position i
        for j in range(i, len(s)):
            # Check if the operation is valid
            if dfs(i, j, s[j]):
                # Find the minimum character that can be replaced to make the substring valid
                min_char = s[j]
                for k in range(j, i, -1):
                    if ord(s[k]) == ord(min_char) + 1:
                        min_char = s[k]
                # Replace the minimum character with the character before it in the alphabet
                s = list(s)
                s[j] = chr(ord(s[j]) - 1 if j!= i else chr(ord(s[j]) - 2))
                s = ''.join(s)
                return s

    return s

