    array = [[0 for _ in range(m)] for _ in range(n)]
    adjacent_pairs_count = [[0 for _ in range(n)] for _ in range(m)]

    # Iterate over each operation in the list of operations.
    for op in operations:
        x, y, color, new_color = op['index'] // m, op['index'] % m, op['color'], op.get('new_color', color)

        # Update the element at the given index with the specified color.
        array[x][y] = color

        # If the index is not on the edge, count the adjacent pairs for the current cell.
        if x > 0:
            if array[x-1][y] == color:
