                if x > 1:
                    adjacent_pairs_count[x-1][y] -= 1
            if y > 0:
                if array[x][y-1] == color:
                    adjacent_pairs_count[x][y] += 1
                    if x > 0:
                        adjacent_pairs_count[x-1][y-1] -= 1
            if y < m - 1:
                if array[x][y+1] == color:
                    adjacent_pairs_count[x][y] += 1
                    if x > 0:
